index access_resource: CREATE INDEX access_resource on access( resource, operation )
index access_subject: CREATE INDEX access_subject on access( subject )
index commits_fired: CREATE INDEX commits_fired on commits(fired, ts)
index log_created: CREATE INDEX log_created on log(created)
table access: CREATE TABLE access ( subject text not null, resource text not null, operation text not null, grant integer not null, granter text not null, created integer not null, primary key ( subject, resource, operation ) )
table acknowledged: CREATE TABLE acknowledged (key text not null, peer text not null, subscriber text not null, last integer not null default 0, primary key (key, peer, subscriber))
table commits: CREATE TABLE commits (seq integer primary key autoincrement, name text not null, kind text not null, row_uid text not null default '', ts integer not null, fired integer not null default 0, attempts integer not null default 0)
table idempotency: CREATE TABLE idempotency (key text primary key, status integer not null, headers blob, body blob, ts integer not null)
table log: CREATE TABLE log (key text not null, peer text not null, sequence integer not null, event text not null, data text not null, created integer not null, primary key (key, peer, sequence))
table pending: CREATE TABLE pending ( peer text not null, key text not null, sequence integer not null, source text not null, target text not null, service text not null, event text not null, message text not null default '', sender_app text not null default '', sender_services text not null default '', content blob not null, received integer not null, primary key (peer, key, sequence) )
table received: CREATE TABLE received (sender text not null, key text not null, last integer not null default 0, seen integer not null default 0, primary key (sender, key))
table sequence: CREATE TABLE sequence (key text not null, peer text not null, last integer not null default 0, primary key (key, peer))
table subscribed: CREATE TABLE subscribed (key text not null, peer text not null, subscriber text not null, updated integer not null default 0, primary key (key, peer, subscriber))
